    public static Geometry Get(string kind)
    {
        if (Cache.TryGetValue(kind, out var geometry)) return geometry;
        geometry = Geometry.Parse(Data.TryGetValue(kind, out var data) ? data : Data["Box"]);
        Cache[kind] = geometry;
        return geometry;
    }
